SELECT id, article_id as articleId, root_id as rootId, parent_id as parentId, parent_nickname as parentNickname, content_html as contentHtml, visitor_id as visitorId, nickname, email_or_qq as emailOrQq, location, user_agent_os as userAgentOs, user_agent_browser as userAgentBrowser, is_approved as isApproved, is_secret as isSecret, is_admin_reply as isAdminReply, create_time as createTime FROM article_comments
AND article_id = #{articleId}
AND is_approved = #{isApproved}
AND parent_id IS NULL
ORDER BY create_time DESC
